script:
class CRMDeal {
	onLoad() {
		this.actions = [
			{
				label: "Create Bid",
				icon: "briefcase",
				onClick: (close) => {
					call("tnl_theme.bid_management.api.create_bid_from_deal", {
						deal: this.doc.name,
					})
						.then((data) => {
							if (!data || !data.name) return
							toast.success(
								data.created
									? __("Bid {0} created", [data.name])
									: __("Bid {0} already exists for this deal", [data.name]),
							)
							window.open(`/app/bid/${data.name}`, "_blank")
						})
						.catch((err) => {
							toast.error(
								(err && err.messages && err.messages.join(", ")) ||
									__("Could not create Bid"),
							)
						})
					if (typeof close === "function") close()
				},
			},
		]
	}
}
